     private suspend fun <T> work(
         label: String,
+        foreground: Boolean = false,
         block: suspend (setProgress: (Double, String) -> Unit) -> T
     ): T? {
         if (busy) {
             say("Занято: дождитесь окончания текущей операции", "err")
             return null
         }
         busy = true
         progress = Prog(0.0, label)
+        acquireWakeLock()
+        if (foreground) runCatching { ProgressService.start(getApplication(), label) }
         return try {
             block { f, t -> progress = Prog(f, t) }
         } catch (e: Throwable) {
             say(e.message ?: e.toString(), "err")
             null
         } finally {
+            if (foreground) runCatching { ProgressService.stop(getApplication()) }
+            releaseWakeLock()
             busy = false
             progress = null
         }
     }

+    private fun acquireWakeLock() {
+        val pm = powerManager ?: return
+        if (wakeLock?.isHeld == true) return
+        runCatching {
+            wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "voicecomic:work").apply {
+                setReferenceCounted(false)
+                acquire(30 * 60 * 1000L)
+            }
+        }
+    }
+
+    private fun releaseWakeLock() {
+        runCatching { wakeLock?.takeIf { it.isHeld }?.release() }
+        wakeLock = null
+    }
