/**
 * Синтез одной реплики системным TTS. Повторы с задержкой и перебором голосов:
 * первый прогон может не успеть инициализировать движок, второй голос может
 * не поддерживать язык и т.п. — реплика не должна теряться молча.
 */
private suspend fun synthesizeOne(
    text: String,
    voice: String?,
    role: Role?
): Pair<String, Double>? {
    if (text.isBlank()) return null
    if (!ensureVoices()) return null
    val pitch = DeviceTts.pitchFactor(role?.pitchNum ?: 0)
    val rate = DeviceTts.rateFactor(role?.rateNum ?: 0)
    val gain = ((role?.volumeNum ?: 100) / 100.0)
    val langPrefix = Defaults.LANG_LOCALE[settings.lang] ?: "ru"
    val pool = VoiceCatalog.forLang(langPrefix).ifEmpty { VoiceCatalog.all() }
    val candidates = buildList<String?> {
        voice?.takeIf { it.isNotBlank() }?.let { add(it) }
        add(null)
        pool.firstOrNull()?.id?.let { if (it != voice) add(it) }
    }
    val cache = getApplication<Application>().cacheDir
    var decoded: Pcm.Decoded? = null
    attempts@ for (attempt in 1..3) {
        for (candidate in candidates) {
            val tmp = File(cache, "tts_${newId().take(8)}.wav")
            val ok = tts.synthesizeToFile(text, candidate, pitch, rate, tmp)
            if (ok) {
                val d = Pcm.readWav(tmp)?.let { (s, sr) -> Pcm.Decoded(Pcm.applyGain(s, gain), sr) }
                    ?: MediaAudioDecoder.decode(tmp)?.let { res -> Pcm.Decoded(Pcm.applyGain(res.samples, gain), res.sr) }
                if (d != null && d.samples.isNotEmpty()) {
                    decoded = d
                    tmp.delete()
                    break@attempts
                }
            }
            tmp.delete()
        }
        if (attempt < 3) delay(200L * attempt)
    }
    val d = decoded ?: return null
    val rel = "bubbles/${newId()}.wav"
    Pcm.writeWav(store.resolve(projectId, rel), Pcm.floatToPcm16(d.samples), d.sr)
    val trim = Pcm.trimSilence(d.samples, d.sr, Timeline.TRIM_THRESHOLD, Timeline.TRIM_MARGIN)
    val dur = if (trim.end > trim.start) {
        maxOf(Timeline.TRIM_MIN_DUR, (trim.end - trim.start).toDouble() / d.sr)
    } else Timeline.TRIM_MIN_DUR
    return rel to dur
}

