input.newString:
    val cache = getApplication<Application>().cacheDir
    var decodedSamples: FloatArray? = null
    var decodedSr = 0
    attempts@ for (attempt in 1..3) {
        for (candidate in candidates) {
            val tmp = File(cache, "tts_${newId().take(8)}.wav")
            val ok = tts.synthesizeToFile(text, candidate, pitch, rate, tmp)
            if (ok) {
                val d = Pcm.readWav(tmp)?.let { (s, sr) -> Pcm.applyGain(s, gain) to sr }
                    ?: MediaAudioDecoder.decode(tmp)?.let { res -> Pcm.applyGain(res.samples, gain) to res.sr }
                if (d != null && d.first.isNotEmpty()) {
                    decodedSamples = d.first
                    decodedSr = d.second
                    tmp.delete()
                    break@attempts
                }
            }
            tmp.delete()
        }
        if (attempt < 3) delay(200L * attempt)
    }
    val samples = decodedSamples ?: return null
    val sr = decodedSr
    val rel = "bubbles/${newId()}.wav"
    Pcm.writeWav(store.resolve(projectId, rel), Pcm.floatToPcm16(samples), sr)
    val trim = Pcm.trimSilence(samples, sr, Timeline.TRIM_THRESHOLD, Timeline.TRIM_MARGIN)
    val dur = if (trim.end > trim.start) {
        maxOf(Timeline.TRIM_MIN_DUR, (trim.end - trim.start).toDouble() / sr)
    } else Timeline.TRIM_MIN_DUR
    return rel to dur
}

